#!/bin/sh
# Rebuild vendor/ from the module cache and reapply the local patches.
#
# vendor/ is regenerated by `go mod vendor`, which wipes every edit made to
# the vendored sources. The patches directory holds the edits this project
# depends on; run this script after `go mod vendor` and before building.
set -e

go mod vendor

for p in patches/*.patch; do
  [ -e "$p" ] || continue
  # A patch already applied is a no-op: -p1 with the a/ b/ prefixes and
  # --no-backup-if-mismatch, and the check below tells us the state.
  if patch -p1 --dry-run --quiet < "$p" >/dev/null 2>&1; then
    patch -p1 < "$p"
    echo "applied $p"
  else
    echo "$p: not applicable (already applied, or the upstream file moved)"
  fi
done

# Every patch must be present in the tree. A dry run against a pristine
# vendor copy proves the patch is not silently missing.
for p in patches/*.patch; do
  [ -e "$p" ] || continue
  if ! patch -p1 --reverse --dry-run --quiet < "$p" >/dev/null 2>&1; then
    echo "MISSING: $p is not applied in vendor/"
    exit 1
  fi
done
echo "vendor/ is patched"
